mapper.select:
select id, user_id, device_id, avatar_id, model, voice, scenario_id, status, started_at, ended_at, error_message, opening_decision_json, created_at, updated_at
from training_session
where id = #{id}

mapper.update:
update training_session
status = #{status}, error_message = #{errorMessage}, ended_at = coalesce(ended_at, #{endedAt}), opening_decision_json = #{openingDecisionJson},
where id = #{id}
